static int portal_skill62(const Combat*g,const float*m,float x,float y,unsigned seed){float z;if(!portal_prepare62(g,m,x,y,&z))return 0;
 float age=g->time+seed*.137f,rotation=g->time*4.36332313f,pulse=fmodf(age,.2f);for(unsigned i=0;i<3;i++){float t=pulse+i*.2f;if(t>=.5f)continue;float phase=t/.5f;portal_cylinder61(m,x,y,z+.16f,12.f*phase,19.5f*phase,.1f,.4f*(1-phase),rotation);}float beamAge=fmodf(age,25),alpha=portal_opacity61(beamAge,25,.3f);portal_cylinder61(m,x,y,z,3.f,3.f,15,alpha,rotation);portal_cylinder61(m,x,y,z,4.f,4.f,13,alpha,rotation);portalDrawn61++;return 1;}
/* Map exits use EF_WARPZONE2: four4s shrinking pulses per layer,1s apart.
 * Original map entity positions/radii are in cells; native cells measure8 units. */
static float portal_random62(unsigned n){n^=n>>16;n*=0x7feb352du;n^=n>>15;n*=0x846ca68bu;n^=n>>16;return (n&65535)/65535.f;}
static int portal_original61(const Combat*g,const float*m,float x,float y,unsigned seed){float z;if(!portal_prepare62(g,m,x,y,&z))return 0;float clock=g->time+seed*.137f;for(unsigned layer=0;layer<2;layer++)for(unsigned i=0;i<4;i++){float age=fmodf(clock+4-i,4),phase=age/4,expand=1-phase,height=1.1f*(phase<.5f?2*phase:2*(1-phase));float alpha=portal_opacity61(age,4,.4f);portal_cylinder61(m,x,y,z,(layer?1.9f:2)*expand*5,(layer?3.2f:3.3f)*expand*5,height*5,alpha,0);}
 float zoom=sqrtf(m[0]*m[0]+m[1]*m[1]);for(unsigned i=0;i<5;i++){float age=fmodf(clock+2-i*.3f,1);float alpha=portal_opacity61(age,1,1);unsigned level=(unsigned)(alpha*16+.5f);if(!level)continue;if(level>16)level=16;unsigned cycle=(unsigned)((clock+2-i*.3f));unsigned key=seed*131+i*409+cycle*7919;float xx=x+(portal_random62(key)*6-3)*8*(1-age),yy=y+(portal_random62(key+1)*6-3)*8*(1-age),zz=z+portal_random62(key+2)*32*age,sx,sy;world_project(m,xx,yy,zz,&sx,&sy);float d=m[8]*xx+m[9]*yy+m[10]*zz+m[11]-WORLD_SPRITE_BIAS,w=50.f*8/35*zoom,top=(13+level-1)*64+.5f;uint32_t*p=pb_begin();p=pb_push1(p,NV097_SET_BEGIN_END,6);p=vertex(p,sx-w*.5f,sy-w*.5f,d,.5f,top);p=vertex(p,sx+w*.5f,sy-w*.5f,d,63.5f,top);p=vertex(p,sx-w*.5f,sy+w*.5f,d,.5f,top+63);p=vertex(p,sx+w*.5f,sy+w*.5f,d,63.5f,top+63);p=pb_push1(p,NV097_SET_BEGIN_END,0);pb_end(p);}portalDrawn61++;return 1;}
/* Large scripted Juperos warp reuses the original map-portal art/animation. */
static int portal_legacy181(const Combat*g,const float*m,float x,float y,unsigned seed){float matrix[16];memcpy(matrix,m,sizeof(matrix));float z=height_at(x,y);for(unsigned r=0;r<3;r++){matrix[r*4+3]-=m[r*4]*x+m[r*4+1]*y+m[r*4+2]*z;for(unsigned c=0;c<3;c++)matrix[r*4+c]*=2;}portalFrame61=0;int drawn=portal_original61(g,matrix,x,y,seed);uint32_t*p=pb_begin();p=pb_push1(p,NV097_SET_BLEND_FUNC_SFACTOR,0x302);p=pb_push1(p,NV097_SET_BLEND_FUNC_DFACTOR,0x303);pb_end(p);return drawn;}
static unsigned portal_draw61(const Combat*g,const float*m,unsigned map){portalFrame61=portalDrawn61=0;if(map>=WORLD_MAP_COUNT)return 0;if(!portalEffects60){portal_release61();return portal_draw52(g,m,map);}for(unsigned i=0;i<WORLD_GATE_COUNT;i++)if(worldGates[i].source==map&&world_gate_enabled64(i)&&world_destination_ready44(worldGates[i].destination))portal_original61(g,m,worldGates[i].x,worldGates[i].y,i);for(unsigned i=0;i<3;i++){const SkillPortal*w=g->portals+i;if(w->expires>g->time&&w->uses)portal_skill62(g,m,w->x,w->y,WORLD_GATE_COUNT+i);}int begun=0;for(unsigned i=0;i<WORLD_GATE_COUNT;i++)if(worldGates[i].source==map&&world_gate_enabled64(i)&&!world_destination_ready44(worldGates[i].destination))portal_marker52(m,worldGates[i].x,worldGates[i].y,12,0xffff4848,&begun);for(unsigned i=0;i<PENDING_WARP_COUNT;i++)if(pendingWarps[i].map==map)portal_marker52(m,pendingWarps[i].x,pendingWarps[i].y,12,0xffff4848,&begun);return portalDrawn61;}
